import { Effect } from 'effect'
type Socket = Readonly<{ send: (text: string) => void }>
type Missing = Readonly<{ _tag: 'Missing'; reason: string }>
type Message = Readonly<{ _tag: 'Completed' }> | Readonly<{ _tag: 'Failed'; error: string }>
declare const ChatSocket: Readonly<{ get: Effect.Effect<Socket, Missing> }>
declare const Message: Readonly<{
  CompletedSendChatMessage: () => Message
  FailedSendChatMessage: (payload: Readonly<{ error: string }>) => Message
}>
export const definition: Readonly<{ execute: (args: Readonly<{ text: string }>) => Effect.Effect<Message> }> = {
  execute: __EXECUTE_CALLBACK__,
}
